local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["a301a9bfb0958798"] = { "Un altro ingegnere! Ehi, è un'ottima occasione per sfoggiare qualche nuovo congegno che sto costruendo!", "." },
  ["a306dff18c881d03"] = { "Premi il pulsante giallo con la scritta «⟦Thieves' Tools=Strumenti dei Ladri⟧».", "." },
  ["a30a96a20170cec5"] = { "Sei davvero potente, {name}. Vieni da me se cerchi altro lavoro.", "." },
  ["a311ae4201a40fad"] = { "Il mio odio è forte <sbuffo>, ma è il momento giusto per raccontarti una storia, {race}.\n\nTanto tempo fa si combatté una battaglia tra dèi. Agamaggan, il nostro grande dio cinghiale, cadde a terra dopo essere stato sconfitto nella Guerra degli Antichi: il suo sangue piovve giù e le sue ossa furono fatte a pezzi. <sbuffo>\n\nGrandi spine spuntarono dalla terra dove il suo sangue toccò il suolo, e il suo teschio adorna una delle caverne a sud.", "." },
  ["a3146c43d3ca1165"] = { "Quale istruttore di professione stai cercando?", "." },
  ["a322a08d10d10464"] = { "No, Gargal. Semplicemente no.", "." },
  ["a33d853d93b8596b"] = { "I vostri sforzi sono del tutto inutili, sciocchi! Non riuscirete mai a sconfiggermi!", "." },
  ["a341782f6123be92"] = { "Fu solo dopo la sua controversa morte che i cavalieri e i guerrieri di Lordaeron presero a indossare armature simili in onore del loro eroe caduto. Se la morte di Mograine fu una grande vittoria per Kel'Thuzad, il martirio che ne seguì si fece sentire fino alla fine della guerra.\n\nDove uno cadde, molti si sarebbero levati...", "." },
  ["a34b289b546b3bd3"] = { "Hai dimostrato abilità nell'apprendere la nostra arte. Hai anche la determinazione per portare a termine una missione per conto mio?", "." },
  ["a35a6151fc576b05"] = { "Grazie ancora, {name}. Ora aspetterò qui finché non sarà sicuro andarsene.", "." },
  ["a362b1a03c3a4544"] = { "Che speranza c'è, quando la mano di un codardo può uccidere il più possente dei possenti? Che speranza, ti chiedo!", "." },
  ["a365ebdadefaf652"] = { "L'abbiamo trovato, {name}.", "." },
  ["a372d4ff9e398074"] = { "Sarai perdonato, Eranikus. Elune ti amerà sempre. Liberati dalle catene che ti comandano!", "." },
  ["a377044779fef412"] = { "È stata la vostra guida a manipolare un bambino in lutto perché tentasse di recuperare la spada. Un bambino che è diventato un uomo con nient'altro che vendetta e odio nel cuore! E per cosa? Non siete più vicini alla spada ora di quanto lo foste cinque anni fa.", "." },
  ["a3786e219dd595e6"] = { "Molto bene, allora...\n\nIl tuo signore ti ha incaricato di sorvegliare i suoi campi di grano da bracconieri e ladri. Una notte, durante la ronda, ti imbatti in un uomo sciupato, con abiti logori, che ruba il grano dal campo. Lo affronti subito, e lui implora immediatamente per la sua vita. Sostiene di rubare il grano per sfamare la sua famiglia, perché il signore di queste terre (il tuo signore) pretende troppe tasse. Il tuo signore è in effetti noto in tutto il paese per le sue tasse esose.\n\nFai la tua scelta.", "." },
  ["a384b822113592f2"] = { "Quando dai i pegni d'amore agli abitanti, riceverai in cambio doni diversi. Alcuni vorrai tenerli e usarli, ma altri si possono riunire e dare al tuo eroe preferito! Visita Kwee Q. Peddlefeet per consegnarli.\n\nKwee si trova vicino a Cairne, Sylvanas e Thrall.", "." },
  ["a38655c598d5f4cd"] = { "La spada non è uno strumento, è un'estensione di te. Mi aspetto di meglio!", "." },
  ["a38ae7223f6a2f83"] = { "Uccidetelo!", "." },
  ["a3900f2e56870338"] = { "Che succede se il moccio ti si congela nel naso?", "." },
  ["a398efff2350886e"] = { "Mi hai portato quelle teste, {name}?", "." },
  ["a39af22f3e5a3f93"] = { "Cosa posso fare per te, <figlio/figlia> <mio/mia>?", "." },
  ["a3a16ecba65e69cf"] = { "Salve, mi chiamo Petra. Alla mia destra c'è il mio kodo, Dadanga. Lavoriamo per la Marshal Expeditions, ormai da qualche anno, da quando Dadanga era un cucciolo.\n\nSe hai torce accese o fiamme libere, ti chiederei di tenerle via, se puoi. A Dadanga il fumo non piace.", "." },
  ["a3a8694bcd22b029"] = { "Sì, <signore/signora>! Mi è stato ordinato di riferire che l'⟦Alliance=Alleanza⟧ ha raccolto tutto il materiale bellico necessario. Mi hanno comunicato che aspettiamo solo che l'⟦Horde=Orda⟧ finisca la sua parte, e poi tutto sarà spedito a ⟦Silithus=Silitus⟧. Grazie, <signore/signora>!", "." },
  ["a3ab047b486b9151"] = { "Dove vuoi andare?", "." },
  ["a3ada0db419b5ccb"] = { "La mamma ha detto di non arrampicarsi più lassù. Lo dico!", "." },
  ["a3b4ca4786cfc842"] = { "HO LA TUA CINTURINA AVVOLTA ATTORNO AL DITO, SMOTTS. NON LA RIVUOI?", "." },
  ["a3b812a174415fb8"] = { "Narain Soothfancy, al tuo servizio! Ingegnere in pensione e maestro indovino! So predirti il futuro prima ancora che accada!", "." },
  ["a3c6304e9607d57b"] = { "Che sollievo che tu sia tornata, Shay. Ti prego, non scappare mai più così! Cosa direi ai tuoi genitori se ti perdessi?", "." },
  ["a3c968fa6ddfe32f"] = { "Ma ciao! Sei qui per imparare la giusta tecnica di una nuova arma?", "." },
  ["a3cc8f58e2d309ee"] = { "Lo stormo cromatico si occuperà di questi intrusi. Parliamo di questioni più urgenti.", "." },
  ["a3d306d63d7c70e7"] = { "Ecco la classifica finale!\n\nThrall: $2200w\n\nCairne: $2201w\n\nSylvanas: $2202w\n\nTotale ⟦Horde=Orda⟧: $2207w\n\nBolvar: $2203w\n\nMagni: $2204w\n\nTyrande: $2205w\n\nTotale ⟦Alliance=Alleanza⟧: $2206w\n\nL'⟦Horde=Orda⟧ ha l'eroe più popolare!", "." },
  ["a3de7cc6a4b74960"] = { "%s torna in vita con un sussulto!", "." },
  ["a3e1eba3f344a026"] = { "Sei <licenziato/licenziata>! <Tosse... Cork si schiarisce la gola.> Cioè, aiuto!", "." },
  ["a3e4eea3794ed215"] = { "Ti piacciono i dolci? A me piacciono i dolci.", "." },
  ["a3e8381856fc7023"] = { "E gli Al'Aketh? Possono aiutarci?", "." },
  ["a3f33c7d254703b6"] = { "La Luce arde forte in te, Davil. Mi divertirò a spegnerla!", "." },
  ["a3f6b893f57b6a67"] = { "Allora supponiamo che tu affronti il lungo e arduo compito di creare l'arma necessaria a infrangere le protezioni demoniache poste sulla triade. Quale sarebbe la tua mossa successiva? Affrontare il Profanatore nella sua tana?\n\n<Loramus ride.>", "." },
})
